contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;

        assert(
            (amount == 10 && !reverted && (afterPot == 0 || afterPot == 10)) ||
            (amount != 10 && reverted && afterPot == beforePot)
        );
    }

    receive() external payable {}
}

